package com.gtamine.visual.editor.betterhud;

import com.gtamine.visual.editor.geometry.Rect;
import java.util.HashMap;
import java.util.Map;
import java.util.regex.Pattern;

/** Decodes the shader program generated by the bundled BetterHud source. No shader edits. */
public record ShaderLayout(int heightBit, int maxBit, int addOffset, int defaultOffset,
                           Map<Integer, Transform> transforms) {
    private static final String NUMBER = "[-+]?(?:\\d+(?:\\.\\d*)?|\\.\\d+)(?:[eE][-+]?\\d+)?";
    private static final Pattern CASE = Pattern.compile("case\\s+(\\d+)\\s*:(.*?)break\\s*;", Pattern.DOTALL);

    public record Transform(double guiX, double guiY, double scaleX, double scaleY,
                            double pivotX, double pivotY, boolean staticX, boolean staticY) {
        public double xScale(double width, double physicalWidth) { return scaleX * (staticX ? width / physicalWidth : 1); }
        public double yScale(double height, double physicalHeight) { return scaleY * (staticY ? height / physicalHeight : 1); }
        public Rect screenRect(Rect raw, int bit, ShaderLayout layout, double width, double height,
                               double physicalWidth, double physicalHeight) {
            double sx = xScale(width, physicalWidth), sy = yScale(height, physicalHeight);
            double x = (raw.x() - width / 2 - pivotX) * sx + pivotX + width * guiX / 100;
            double y = (raw.y() - (bit * (double)(1 << layout.heightBit)) - layout.addOffset
                    - layout.defaultOffset - pivotY) * sy + pivotY + height * guiY / 100;
            return new Rect(x, y, raw.width() * sx, raw.height() * sy);
        }
    }

    public static ShaderLayout parse(String source) {
        if (!source.contains("xGui") || !source.contains("HEIGHT_BIT") || !source.contains("ADD_OFFSET")) {
            throw new IllegalArgumentException("Not a supported BetterHud shader");
        }
        int height = constant(source, "HEIGHT_BIT"), max = constant(source, "MAX_BIT");
        if (height != 13 || max != 10) throw new IllegalArgumentException("Unsupported shader encoding");
        Map<Integer, Transform> transforms = new HashMap<>();
        var cases = CASE.matcher(source);
        while (cases.find()) {
            String body = cases.group(2);
            double[] x = scale(body, "x"), y = scale(body, "y");
            transforms.put(Integer.parseInt(cases.group(1)), new Transform(
                    gui(body, "x"), gui(body, "y"), x[0], y[0], x[1], y[1], x[2] != 0, y[2] != 0));
        }
        if (transforms.isEmpty()) throw new IllegalArgumentException("No shader layouts");
        return new ShaderLayout(height, max, constant(source, "ADD_OFFSET"),
                constant(source, "DEFAULT_OFFSET"), Map.copyOf(transforms));
    }

    private static int constant(String source, String name) {
        var match = Pattern.compile("#define\\s+" + name + "\\s+(\\d+)").matcher(source);
        if (!match.find()) throw new IllegalArgumentException("Missing " + name);
        return Integer.parseInt(match.group(1));
    }

    private static double gui(String body, String axis) {
        var match = Pattern.compile(axis + "Gui\\s*=\\s*ui\\." + axis + "\\s*\\*\\s*(" + NUMBER + ")\\s*/\\s*100(?:\\.0)?").matcher(body);
        if (match.find()) return Double.parseDouble(match.group(1));
        if (body.contains(axis + "Gui")) throw new IllegalArgumentException("Unsupported GUI anchor");
        return 0;
    }

    private static double[] scale(String body, String axis) {
        String a = "pos\\." + axis;
        var match = Pattern.compile(a + "\\s*=\\s*\\(" + a + "\\s*-\\s*\\((" + NUMBER + ")\\)\\)\\s*\\*\\s*(" + NUMBER
                + ")(\\s*\\*\\s*uiScreen\\." + axis + ")?\\s*\\+\\s*\\((" + NUMBER + ")\\)").matcher(body);
        if (match.find()) {
            if (!match.group(1).equals(match.group(4))) throw new IllegalArgumentException("Unsupported scale pivot");
            double factor = Double.parseDouble(match.group(2));
            if (factor <= 0 || !Double.isFinite(factor)) throw new IllegalArgumentException("Invalid scale");
            return new double[]{factor, Double.parseDouble(match.group(1)), match.group(3) == null ? 0 : 1};
        }
        if (body.contains("pos." + axis)) throw new IllegalArgumentException("Unsupported shader transform");
        return new double[]{1, 0, 0};
    }
}
